// GENERATED by apps/api/scripts/sync-puzzle-adapter.mjs; edit the domain source, then regenerate.
// Extra stats: a per-scenario grid of 20 stat nodes bought with Farm crops, six of them active (D235,
// docs/design/constellations.md#extra-stats).

import { farmCropFor } from './farm/catalog'
import { FARM_SAFE_ID_PATTERN, type ExtraStatUnlockMovement, type FarmCropId } from './farm/types'
import { MAX_SCENARIO_TIER } from './scenarios'
import { STATS, type StatKey, type Stats } from './types'

/** Four nodes of each stat in a scenario's grid. */
export const EXTRA_STAT_NODES_PER_STAT = 4
/** At most six grid nodes pay at once; which six is a free choice. */
export const EXTRA_STAT_SLOTS = 6
/** Raw points one active node pays: the 240-point minor-stat pool over six slots, as Produce nodes paid (D134, D205). */
export const EXTRA_STAT_NODE_VALUE = 40

export type ExtraStatNodeId = `${StatKey}-${1 | 2 | 3 | 4}`

export interface ExtraStats {
  /** How many of each stat's four nodes are bought, in order: 0–4. */
  unlocked: Record<StatKey, number>
  /** The active nodes, at most six, each bought; kept in grid order. */
  active: ExtraStatNodeId[]
}

export const emptyExtraStats = (): ExtraStats => ({
  unlocked: { speed: 0, stamina: 0, power: 0, guts: 0, wit: 0 },
  active: [],
})

export const extraStatNodeId = (stat: StatKey, index: number): ExtraStatNodeId => `${stat}-${index}` as ExtraStatNodeId

/** Every node of the grid, stat by stat (the Stats order), first to fourth. */
export const EXTRA_STAT_NODE_IDS: readonly ExtraStatNodeId[] = STATS.flatMap((stat) =>
  Array.from({ length: EXTRA_STAT_NODES_PER_STAT }, (_, index) => extraStatNodeId(stat, index + 1)))

export function parseExtraStatNodeId(value: unknown): { stat: StatKey; index: number } | null {
  if (typeof value !== 'string' || !EXTRA_STAT_NODE_IDS.includes(value as ExtraStatNodeId)) return null
  const [stat, index] = value.split('-') as [StatKey, string]
  return { stat, index: Number(index) }
}

const gridOrder = (left: ExtraStatNodeId, right: ExtraStatNodeId): number =>
  EXTRA_STAT_NODE_IDS.indexOf(left) - EXTRA_STAT_NODE_IDS.indexOf(right)

/** A stat's `index`-th node costs `index` of that stat's scenario crop: 1, 2, 3 and 4, so ten for a full row (D235). */
export const extraStatUnlockCost = (index: number): number => index

export const isExtraStatNodeUnlocked = (extra: ExtraStats, nodeId: ExtraStatNodeId): boolean => {
  const node = parseExtraStatNodeId(nodeId)
  return node !== null && node.index <= extra.unlocked[node.stat]
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

/** Strict and canonical: every stat's count 0–4, and at most six distinct bought nodes active, in grid order. */
export function parseExtraStats(value: unknown): ExtraStats | null {
  if (!isRecord(value) || Object.keys(value).length !== 2 || !isRecord(value.unlocked) || !Array.isArray(value.active)) return null
  const unlockedRaw = value.unlocked
  if (Object.keys(unlockedRaw).length !== STATS.length) return null
  const unlocked = {} as Record<StatKey, number>
  for (const stat of STATS) {
    const count = unlockedRaw[stat]
    if (!Number.isSafeInteger(count) || (count as number) < 0 || (count as number) > EXTRA_STAT_NODES_PER_STAT) return null
    unlocked[stat] = count as number
  }
  if (value.active.length > EXTRA_STAT_SLOTS) return null
  const active: ExtraStatNodeId[] = []
  for (const raw of value.active) {
    const node = parseExtraStatNodeId(raw)
    if (!node || node.index > unlocked[node.stat]) return null
    const id = raw as ExtraStatNodeId
    if (active.length > 0 && gridOrder(active.at(-1)!, id) >= 0) return null
    active.push(id)
  }
  return { unlocked, active }
}

/** How many active nodes pay each stat. */
export function extraStatCounts(extra: ExtraStats): Stats {
  const counts: Stats = { speed: 0, stamina: 0, power: 0, guts: 0, wit: 0 }
  for (const id of extra.active) counts[parseExtraStatNodeId(id)!.stat] += 1
  return counts
}

/** Turn one bought node on or off. Free and reversible; at most six are on. */
export function toggleExtraStat(extra: ExtraStats, nodeId: ExtraStatNodeId, on: boolean): ExtraStats {
  if (!isExtraStatNodeUnlocked(extra, nodeId)) throw new Error('That Extra stat node is not unlocked yet')
  const others = extra.active.filter((id) => id !== nodeId)
  if (!on) return { unlocked: { ...extra.unlocked }, active: others }
  if (others.length >= EXTRA_STAT_SLOTS) throw new Error(`All ${EXTRA_STAT_SLOTS} Extra stat slots are in use; turn one off first`)
  return { unlocked: { ...extra.unlocked }, active: [...others, nodeId].sort(gridOrder) }
}

export const extraStatUnlockMovementId = (umaId: string, tier: number, nodeId: ExtraStatNodeId): string =>
  `extra:${umaId}:${tier}:${nodeId}`

export interface ExtraStatUnlockCommand {
  extra: ExtraStats
  nodeId: ExtraStatNodeId
  cropId: FarmCropId
  cost: number
  movement: ExtraStatUnlockMovement
  quantityBefore: number
  quantityAfter: number
}

/**
 * Buys a stat's next node with that many of the scenario's crop for the stat, consumed for good. A bought node turns on
 * at once while a slot is free. Training Level plays no part (D235).
 */
export function resolveExtraStatUnlock(input: {
  umaId: string
  tier: number
  extra: ExtraStats
  stat: StatKey
  quantity: number
  now: number
}): ExtraStatUnlockCommand {
  if (!FARM_SAFE_ID_PATTERN.test(input.umaId) || !Number.isSafeInteger(input.tier) || input.tier < 1 ||
    input.tier > MAX_SCENARIO_TIER || !STATS.includes(input.stat) || !Number.isSafeInteger(input.now) || input.now < 0) {
    throw new Error('Extra stat unlock is invalid')
  }
  const owned = input.extra.unlocked[input.stat]
  if (owned >= EXTRA_STAT_NODES_PER_STAT) throw new Error('Every node of that stat is already unlocked')
  const index = owned + 1
  const nodeId = extraStatNodeId(input.stat, index)
  const cost = extraStatUnlockCost(index)
  const crop = farmCropFor(input.tier, input.stat)
  if (!crop) throw new Error('That scenario has no crop for this stat')
  if (!Number.isSafeInteger(input.quantity) || input.quantity < cost) throw new Error(`Unlocking needs ${cost} ${crop.name}`)

  const unlocked = { ...input.extra.unlocked, [input.stat]: index }
  const active = input.extra.active.length < EXTRA_STAT_SLOTS
    ? [...input.extra.active, nodeId].sort(gridOrder)
    : [...input.extra.active]
  const movement: ExtraStatUnlockMovement = {
    id: extraStatUnlockMovementId(input.umaId, input.tier, nodeId),
    itemId: crop.id,
    delta: -cost,
    reason: 'extra-stat-unlock',
    source: { kind: 'extra-stat-unlock', umaId: input.umaId, tier: input.tier, nodeId },
    createdAt: input.now,
  }
  if (!FARM_SAFE_ID_PATTERN.test(movement.id)) throw new Error('Extra stat evidence id is too long')
  return {
    extra: { unlocked, active },
    nodeId,
    cropId: crop.id,
    cost,
    movement,
    quantityBefore: input.quantity,
    quantityAfter: input.quantity - cost,
  }
}

/**
 * The grid a v11 unit's Produce nodes become (D235): each filled Produce node buys and turns on the next node of its stat,
 * free. A stat holds four, so a fifth or sixth of one stat is dropped and its slot opens.
 */
export function extraStatsFromProduce(stats: readonly StatKey[]): ExtraStats {
  let extra = emptyExtraStats()
  for (const stat of stats) {
    const index = extra.unlocked[stat] + 1
    if (index > EXTRA_STAT_NODES_PER_STAT) continue
    const nodeId = extraStatNodeId(stat, index)
    extra = { unlocked: { ...extra.unlocked, [stat]: index }, active: [...extra.active, nodeId].sort(gridOrder) }
  }
  return extra
}
